-- ICT371 Question 9: Farmer Cooperative Maize Deliveries (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q09_maize; USE ict371_q09_maize;
CREATE TABLE farmers(farmer_id INT AUTO_INCREMENT PRIMARY KEY,farmer_number VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL);
CREATE TABLE deliveries(delivery_id BIGINT AUTO_INCREMENT PRIMARY KEY,farmer_id INT NOT NULL,grade ENUM('A','B','C') NOT NULL,weight_kg DECIMAL(12,2) NOT NULL,unit_rate DECIMAL(8,2) NOT NULL,total_value DECIMAL(14,2) NOT NULL,delivered_on DATE NOT NULL,is_paid BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(farmer_id) REFERENCES farmers(farmer_id),CHECK(weight_kg>0 AND unit_rate>0 AND total_value>=0));
CREATE TABLE daily_purchases(purchase_date DATE PRIMARY KEY,total_weight DECIMAL(14,2) NOT NULL,total_value DECIMAL(16,2) NOT NULL);
INSERT INTO farmers(farmer_number,full_name) VALUES('F001','Mwila'),('F002','Chanda'),('F003','Phiri');
DELIMITER $$
CREATE FUNCTION fn_maize_rate(p_grade CHAR(1)) RETURNS DECIMAL(8,2) DETERMINISTIC NO SQL BEGIN IF p_grade IS NULL OR p_grade NOT IN('A','B','C') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Grade must be A, B or C'; END IF; RETURN CASE p_grade WHEN 'A' THEN 5.00 WHEN 'B' THEN 4.00 ELSE 3.00 END; END$$
CREATE TRIGGER trg_delivery_value BEFORE INSERT ON deliveries FOR EACH ROW BEGIN IF NEW.weight_kg IS NULL OR NEW.weight_kg<=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Weight must be positive'; END IF; SET NEW.unit_rate=fn_maize_rate(NEW.grade); SET NEW.total_value=NEW.weight_kg*NEW.unit_rate; END$$
CREATE TRIGGER trg_delivery_value_update BEFORE UPDATE ON deliveries FOR EACH ROW BEGIN IF NEW.weight_kg IS NULL OR NEW.weight_kg<=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Weight must be positive'; END IF; SET NEW.unit_rate=fn_maize_rate(NEW.grade); SET NEW.total_value=NEW.weight_kg*NEW.unit_rate; END$$
CREATE PROCEDURE pr_receive_delivery(IN p_farmer_id INT,IN p_grade CHAR(1),IN p_weight DECIMAL(12,2),IN p_date DATE) BEGIN IF NOT EXISTS(SELECT 1 FROM farmers WHERE farmer_id=p_farmer_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown farmer'; END IF; IF p_weight IS NULL OR p_weight<=0 OR p_date IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid weight or delivery date'; END IF; INSERT INTO deliveries(farmer_id,grade,weight_kg,unit_rate,total_value,delivered_on,is_paid) VALUES(p_farmer_id,p_grade,p_weight,0,0,p_date,FALSE); END$$
CREATE PROCEDURE pr_refresh_purchases(IN p_day DATE) BEGIN INSERT INTO daily_purchases(purchase_date,total_weight,total_value) SELECT p_day,COALESCE(SUM(weight_kg),0),COALESCE(SUM(total_value),0) FROM deliveries WHERE delivered_on=p_day ON DUPLICATE KEY UPDATE total_weight=VALUES(total_weight),total_value=VALUES(total_value); END$$
DELIMITER ;
INSERT INTO deliveries(farmer_id,grade,weight_kg,unit_rate,total_value,delivered_on,is_paid) VALUES(1,'A',100,0,0,CURRENT_DATE,FALSE),(1,'B',80,0,0,CURRENT_DATE,TRUE),(2,'C',120,0,0,CURRENT_DATE,FALSE),(2,'A',60,0,0,CURRENT_DATE,TRUE),(3,'B',90,0,0,CURRENT_DATE,FALSE),(3,'C',75,0,0,CURRENT_DATE,TRUE);
CREATE VIEW v_farmer_amount_due AS SELECT f.farmer_number,f.full_name,COALESCE(SUM(CASE WHEN d.is_paid=FALSE THEN d.total_value ELSE 0 END),0) amount_due FROM farmers f LEFT JOIN deliveries d ON d.farmer_id=f.farmer_id GROUP BY f.farmer_id,f.farmer_number,f.full_name;
CREATE INDEX ix_deliveries_farmer_date ON deliveries(farmer_id,delivered_on);
EXPLAIN SELECT delivery_id,grade,weight_kg,total_value FROM deliveries WHERE farmer_id=1 AND delivered_on BETWEEN '2026-01-01' AND '2026-12-31';
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_refresh_purchases ON SCHEDULE EVERY 1 DAY STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL 1 DAY,'01:30:00')) DO CALL pr_refresh_purchases(CURRENT_DATE-INTERVAL 1 DAY);
